describe('Countdown Timer', () => {
    beforeEach(() => {
        cy.visit('/'); // Adjust the URL to the application page with the countdown timer
    });

    it('should display the countdown timer starting from 60 seconds', () => {
        cy.get('.countdown-timer').should('contain', '60');
    });

    it('should update the countdown timer every second', () => {
        cy.get('.countdown-timer').then(($timer) => {
            const initialTime = parseInt($timer.text(), 10);
            cy.wait(1000); // Wait for 1 second
            cy.get('.countdown-timer').should(($newTimer) => {
                const newTime = parseInt($newTimer.text(), 10);
                expect(newTime).to.eq(initialTime - 1);
            });
        });
    });
});
